nonpassing_cases.message:
  Expected: String containing "#unity-canvas { position: fixed; left: 0; top: 0; width: 100%; height: 100%;"
  But was:  "<!DOCTYPE html>
<html lang="en-us">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, height=device-height, initial-scale=1.0, user-scalable=no, viewport-fit=cover">
    <title>{{{ PRODUCT_NAME }}}</title>
    <link rel="icon" type="image/x-icon" href="favicon.ico">
    <style>
      html, body { margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden; background: #0e1626; }
      #player-layout { display: grid; grid-template-columns: minmax(0, 1fr) clamp(18rem, 26vw, 24rem);
        width: 100%; height: 100dvh; box-sizing: border-box;
        padding: env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left); }
      #game-view { position: relative; min-width: 0; min-height: 0; }
      #unity-canvas { width: 100%; height: 100%; background: #0e1626; display: block; }
      #companion { min-width: 0; overflow-y: auto; padding: 12px; border-left: 1px solid #c4a05c;
        color: #ece4d2; font: 16px/1.5 Georgia, "Times New Roman", serif; overflow-wrap: anywhere; }
      #companion h2 { font-size: 1.2em; }
      #companion p { white-space: pre-wrap; }
      #companion li[aria-disabled="true"] { color: #b8b0a0; }
      @media (max-width: 700px) {
        #player-layout { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) minmax(8rem, 30dvh); }
        #companion { border-left: 0; border-top: 1px solid #c4a05c; }
      }
      #loading { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); color: #ece4d2;
                 font: 20px Georgia, "Times New Roman", serif; text-align: center; }
      #bar { width: 320px; height: 4px; margin-top: 12px; border: 1px solid #c4a05c; }
      #fill { width: 0; height: 100%; background: #c4a05c; }
      #error { display: none; position: absolute; left: 10%; right: 10%; top: 40%; color: #de7868; background: #0e1626;
               border: 1px solid #c4a05c; padding: 16px; font: 16px Georgia, serif; white-space: pre-wrap; }
    </style>
  </head>
  <body>
    <div id="player-layout">
      <main id="game-view">
        <canvas id="unity-canvas" tabindex="-1"></canvas>
        <div id="loading">Statecraft: Israel<div id="bar"><div id="fill"></div></div></div>
        <div id="error"></div>
      </main>
      <aside id="companion" aria-label="Statecraft: Israel">
        <p id="companion-focus" dir="auto"></p>
        <div id="companion-reading"></div>
        <p id="companion-status" dir="auto" role="status"></p>
      </aside>
    </div>
    <script>
      // Unity keeps the render size matched to the canvas's CSS size, so the UI Toolkit panel
      // (ScaleWithScreenSize, 1920x1080, match 0.5) rescales on every browser resize.
      var loaderUrl = "Build/{{{ LOADER_FILENAME }}}";
      var config = {
        arguments: [],
        dataUrl: "Build/{{{ DATA_FILENAME }}}",
        frameworkUrl: "Build/{{{ FRAMEWORK_FILENAME }}}",
#if USE_THREADS
        workerUrl: "Build/{{{ WORKER_FILENAME }}}",
#endif
#if USE_WASM
        codeUrl: "Build/{{{ CODE_FILENAME }}}",
#endif
#if SYMBOLS_FILENAME
        symbolsUrl: "Build/{{{ SYMBOLS_FILENAME }}}",
#endif
        streamingAssetsUrl: "StreamingAssets",
        companyName: {{{ JSON.stringify(COMPANY_NAME) }}},
        productName: {{{ JSON.stringify(PRODUCT_NAME) }}},
        productVersion: {{{ JSON.stringify(PRODUCT_VERSION) }}},
        // Queue IndexedDB persistence when a file under /idbfs closes; completion is asynchronous.
        // GameStart's save receipt observes that commit, without starting a concurrent manual sync.
        autoSyncPersistentDataPath: true,
      };
      // Issue #437: the Build/ files are named by their content hash, and this page names its build's files. A browser may
      // show this page from its cache after a newer build replaced them (a server that sends no Cache-Control, such as
      // python3 -m http.server, lets it), so ask the server for the current page and load the files that one names. The
      // fetch skips the cache and stores the copy it gets ("reload"), so the next visit runs the current page. When it
      // fails (file://, offline, or not this template), keep this page's own names.
      var FRESH_KEYS = ["loaderUrl", "dataUrl", "frameworkUrl", "workerUrl", "codeUrl", "symbolsUrl"];
      function useCurrentPage(html) {
        var found = {};
        FRESH_KEYS.forEach(function (key) {
          var m = html.match(new RegExp("\\b" + key + '\\s*[:=]\\s*"(Build/[^"]+)"'));
          if (m) found[key] = m[1];
        });
        if (!found.loaderUrl || !found.dataUrl) return;
        loaderUrl = found.loaderUrl;
        FRESH_KEYS.slice(1).forEach(function (key) {
          if (found[key]) config[key] = found[key]; else delete config[key];
        });
      }
      function fail(message) {
        var e = document.getElementById("error");
        e.textContent = "Statecraft could not start:\n" + message;
        e.style.display = "block";
        console.error("BOOT FAIL " + message);
      }
      // B is output only. Install after the loader resolves; no new font, library, asset or boot request.
      function mountCompanion() {
        var panel = document.getElementById("companion"), reading = document.getElementById("companion-reading");
        var focus = document.getElementById("companion-focus"), status = document.getElementById("companion-status");
        var cardKey, statusText, statusTurn;
        function string(value) { return typeof value === "string"; }
        function strings(value) { return Array.isArray(value) && value.every(string); }
        function valid(p) {
          return p && (p.language === "en" || p.language === "he") && Number.isSafeInteger(p.turn) && p.turn >= 0
            && [p.screen, p.focus, p.title, p.body, p.status].every(string) && strings(p.context)
            && Array.isArray(p.choices) && p.choices.every(function (c) {
              return c && string(c.text) && typeof c.enabled === "boolean" && strings(c.notes);
            });
        }
        function text(tag, value) {
          var node = document.createElement(tag);
          node.setAttribute("dir", "auto"); node.textContent = value;
          return node;
        }
        window.statecraftCompanionPush = function (json) {
          var p;
          try { p = JSON.parse(json); } catch (_) { return false; }
          if (!valid(p)) return false; // reject the whole payload before touching the last good panel
          var key = JSON.stringify([p.language, p.screen, p.title, p.body, p.context, p.choices]);
          if (key !== cardKey) {
            var content = document.createElement("div");
            if (p.screen) content.appendChild(text("h2", p.screen));
            if (p.title) content.appendChild(text("h2", p.title));
            p.context.forEach(function (line) { content.appendChild(text("p", line)); });
            if (p.body) content.appendChild(text("p", p.body));
            if (p.choices.length) {
              var list = document.createElement("ol");
              p.choices.forEach(function (choice) {
                var item = text("li", choice.text);
                item.setAttribute("aria-disabled", choice.enabled ? "false" : "true");
                choice.notes.forEach(function (note) { item.appendChild(text("p", note)); });
                list.appendChild(item);
              });
              content.appendChild(list);
            }
            reading.replaceChildren(content); cardKey = key;
          }
          panel.setAttribute("lang", p.language); // fixed allowlist, independent of game text
          if (focus.textContent !== p.focus) focus.textContent = p.focus;
          if (statusText !== p.status || statusTurn !== p.turn) {
            status.replaceChildren(document.createTextNode(p.status));
            statusText = p.status; statusTurn = p.turn;
          }
          return true;
        };
      }
      function start() {
        var script = document.createElement("script");
        script.src = loaderUrl;
        script.onerror = function () { fail("could not load " + loaderUrl); };
        script.onload = function () {
          createUnityInstance(document.querySelector("#unity-canvas"), config, function (progress) {
            document.getElementById("fill").style.width = (100 * progress) + "%";
          }).then(function () {
            mountCompanion();
            document.getElementById("loading").style.display = "none";
          }).catch(fail);
        };
        document.body.appendChild(script);
      }
      fetch(location.href.split("#")[0], { cache: "reload" })
        .then(function (r) { return r.ok ? r.text() : ""; })
        .then(useCurrentPage)
        .catch(function () {})
        .then(start);
    </script>
  </body>
</html>
